"""Adversarial worker problems: huge loads, tiny capacities, binding demands."""
import json
import random
import sys

sys.path.insert(0, '/workspace/submission')


def build(seed=0, mode='route', nworkers=1, cap_mode='tiny', demand_scale=1000):
    rng = random.Random(seed)
    nodes = 32
    edges = []
    pairs = [(u, v) for u in range(nodes) for v in range(nodes) if u != v]
    rng.shuffle(pairs)
    caps = ([1] if cap_mode == 'tiny' else [1, 2, 3]) * 100
    for u, v in pairs[:64]:
        edges.append([u, v, rng.choice(caps)])
    adj = {}
    for i, e in enumerate(edges):
        adj.setdefault(e[0], []).append(i)

    def walk(s, t):
        for _ in range(60):
            path, cur, seen = [], s, {s}
            while len(path) < 12:
                outs = [i for i in adj.get(cur, []) if edges[i][1] not in seen]
                if not outs:
                    break
                i = rng.choice(outs)
                path.append(i); seen.add(edges[i][1]); cur = edges[i][1]
                if cur == t:
                    return path
            if path and cur == t:
                return path
        return None
    coms = []
    for k in range(24):
        s = rng.randrange(nodes); t = rng.randrange(nodes)
        while t == s:
            t = rng.randrange(nodes)
        paths, guard = [], 0
        while len(paths) < 4 and guard < 80:
            guard += 1
            w = walk(s, t)
            if w is None:
                continue
            if any(p is not None and tuple(p) == tuple(w) for p in paths):
                continue
            paths.append(w)
        if not paths:
            continue
        coms.append({'source': s, 'sink': t, 'demand': demand_scale, 'paths': paths})
    ids = list(range(len(coms)))
    workers = []
    per = max(1, (len(ids) + nworkers - 1) // nworkers)
    for w in range(nworkers):
        chunk = sorted(ids[w * per:(w + 1) * per])
        if chunk:
            workers.append(chunk)
    if not workers:
        workers = [ids]
    events = []
    for i in range(8):
        events.append({'op': 'issue', 'id': 7000 + i, 'worker': rng.randrange(len(workers))})
        events.append({'op': 'deliver', 'id': 7000 + i})
        events.append({'op': 'step'})
        events.append({'op': 'audit'})
    a = rng.randint(1, 16); b = rng.randint(a // 2 + 1, a)
    return {'nodes': nodes, 'edges': edges, 'commodities': coms, 'workers': workers,
            'quorum': len(workers), 'max_lag': 2, 'relax': [a, b],
            'rho': rng.randint(1, 8), 'mode': mode, 'events': events}


if __name__ == '__main__':
    out = []
    for mode in ['route', 'admit']:
        for nw in [1, 2, 8]:
            for cm in ['tiny', 'small']:
                out.append(build(3, mode, nw, cm))
    sys.stdout.write(json.dumps({'cases': out}, separators=(',', ':')))
